سؤال امتحان: البرنامج بيصنّف عدد. شو بيطبع لـ <bdi dir="ltr">n = -6</bdi>؟<div class="codepair"><pre class="code" dir="ltr">n = -6
if n &gt; 0 and n % 2 == 0:
    kind = "positive even"
elif n &gt; 0:
    kind = "positive odd"
elif n == 0:
    kind = "zero"
else:
    kind = "negative"
if n % 3 == 0:
    kind = kind + " /3"
print(kind)</pre><div class="out"><div class="tt">اللي بيطلع على الشاشة</div><pre dir="ltr">negative /3</pre></div></div>
